package com.bank.qa.perftypes;

// Models response time, error rate, and a slow memory leak vs load/time.
class ServiceModel {
    private final int capacityTps;   // sustainable throughput
    private double leakedMb = 0;      // grows during soak if leaking

    ServiceModel(int capacityTps) { this.capacityTps = capacityTps; }

    // p95 latency grows as load approaches/exceeds capacity.
    double p95Ms(int tps) {
        double util = (double) tps / capacityTps;
        double base = 50;
        return util <= 1.0 ? base + util * 100 : base + 150 + (util - 1.0) * 800; // sharp past capacity
    }

    // Error rate ~0 within capacity, climbs when oversubscribed.
    double errorPct(int tps) {
        return tps <= capacityTps ? 0.0 : Math.min(60.0, (tps - capacityTps) * 100.0 / capacityTps);
    }

    int throughput(int offeredTps) { return Math.min(offeredTps, capacityTps); } // cannot exceed capacity

    // Soak: each hour leaks memory if the leak flag is on.
    void soakHour(boolean leaking) { if (leaking) leakedMb += 40; }
    double leakedMb() { return leakedMb; }
}
