package com.bank.qa.perftypes;

import java.util.logging.*;

public class PerfTypesDemo {
    private static final Logger log = Logger.getLogger(PerfTypesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PtLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        ServiceModel svc = new ServiceModel(1000); // sustains 1000 TPS

        // LOAD: normal/peak expected load — verify it meets SLA.
        int load = 900;
        log.info(String.format("LOAD @%dTPS: p95=%.0fms err=%.1f%% tput=%d -> %s",
            load, svc.p95Ms(load), svc.errorPct(load), svc.throughput(load),
            (svc.p95Ms(load) < 200 && svc.errorPct(load) < 1) ? "MEETS SLA" : "BREACH"));

        // STRESS: push beyond capacity — find breaking point + failure mode.
        for (int tps : new int[]{1200, 1600, 2000}) {
            log.info(String.format("STRESS @%dTPS: p95=%.0fms err=%.1f%% (breaking/degrading)",
                tps, svc.p95Ms(tps), svc.errorPct(tps)));
        }

        // SPIKE: sudden jump from low to very high for a short burst.
        log.info("SPIKE: 100 -> 1800 TPS instantly");
        log.info(String.format("  before: p95=%.0fms err=%.1f%%", svc.p95Ms(100), svc.errorPct(100)));
        log.info(String.format("  spike : p95=%.0fms err=%.1f%% (survives? autoscale/queue)",
            svc.p95Ms(1800), svc.errorPct(1800)));

        // SOAK: sustained load over many hours — detect memory leak.
        log.info("SOAK: 800 TPS for 12 hours, watching memory");
        boolean leaking = true; // simulate a leak
        for (int h = 1; h <= 12; h++) svc.soakHour(leaking);
        log.info(String.format("  after 12h: leaked=%.0fMB -> %s",
            svc.leakedMb(), svc.leakedMb() > 100 ? "MEMORY LEAK DETECTED (would OOM in prod)" : "stable"));
    }
}

